def verify(solution):
    n = len(solution)
    # Check rows (implicitly fine since one per row)
    # Check columns
    if len(set(solution)) != n:
        return False, "Duplicate column"
    # Check diagonals
    for i in range(n):
        for j in range(i+1, n):
            if abs(solution[i] - solution[j]) == abs(i - j):
                return False, f"Diagonal conflict between rows {i} and {j}"
    return True, "Valid"

sol = [0, 2, 4, 1, 3, 8, 10, 12, 14, 20, 22, 24, 19, 21, 23, 25, 9, 6, 15, 11, 7, 5, 17, 13, 18, 16]
print(verify(sol))
